import SwiftUI
struct SettingsScreen: View {
    @State private var locked = true
    var body: some View {
        VStack {
            Toggle("Блокировка", isOn: $locked)
            Text(locked ? "Заблокировано" : "Доступно")
            Button("Помощь") { }
        }
    }
}

disabled на общем контейнере блокировал и сам переключатель. Удаление общего запрета сохраняет управление; Text показывает статус из locked.

