import SwiftUI
struct ChannelScreen: View {
    @State private var subscribed = false
    var followers: Int { 120 + (subscribed ? 1 : 0) }
    var body: some View {
        VStack {
            Text("Подписчиков: \(followers)")
            SubscribeButton(isSubscribed: subscribed) { subscribed.toggle() }
        }
    }
}
struct SubscribeButton: View {
    let isSubscribed: Bool
    let onToggle: () -> Void
    var body: some View {
        Button(isSubscribed ? "Отписаться" : "Подписаться", action: onToggle)
    }
}

Вниз идёт значение subscribed — кнопке оно нужно только для подписи. Наверх — действие: решение меняет владелец через toggle(). followers вычисляется, поэтому после нажатия станет 121, после повторного — снова 120.
